**Example 1:  Basic Process Creation (Windows - using `CreateProcess`)**

```c++
#include <iostream>
#include <windows.h>

int main() {
    // Create a new process
    STARTUPINFO si;
    PROCESS_INFORMATION pi;

    ZeroMemory(&si, sizeof(si));
    si.cb = sizeof(si);
    ZeroMemory(&pi, sizeof(pi));

    // Create the process
    if (!CreateProcess(
        "cmd.exe",  // Command to execute
        NULL,        // Command line (optional)
        NULL,        // Process handle
        NULL,        // Thread handle
        FALSE,       // Start new process
        CREATE_NO_WINDOW, // Window creation flags
        NULL,        // Environment block
        NULL,        // Current directory
        &si,         // Startup information
        &pi)        // Process information
    {
        cerr << "Error creating process: " << GetLastError() << endl;
        return 1;
    }

    // Wait for the process to finish
    WaitForSingleObject(pi.hProcess, INFINITE);

    // Close handles
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);

    return 0;
}
```

**Explanation:**

* **`CreateProcess`:** This function is the core of process creation.  It takes parameters like the command to execute, environment variables, and window flags.
* **`STARTUPINFO` and `PROCESS_INFORMATION`:** These structures hold information about the new process.
* **`WaitForSingleObject`:**  This waits for the process to complete.
* **`CloseHandle`:**  Releases the handles to the process and thread.

