#include <fstream>
#include <string>

int main() {
    std::string filename = "my_file.txt"; // Replace with your file

    // Open the file
    std::ifstream file(filename);

    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 1;
    }

    // Read the file content
    std::string line;
    while (std::getline(file, line)) {
        std::cout << line << std::endl;
    }

    // Close the file
    file.close();

    return 0;
}
```

**Explanation:**

* **`ifstream`:**  This class is used for reading files.
* **`std::getline`:** Reads a line from the file.
* **`file.is_open()`:** Checks if the file was opened successfully.
* **`file.close()`:** Closes the file.

